--
-- Triggers `module`
--
DROP TRIGGER IF EXISTS `after_insert_module`;
DELIMITER //
CREATE TRIGGER `after_insert_module` AFTER INSERT ON `module`
 FOR EACH ROW BEGIN
DECLARE a,b  int;
SET b=(SELECT annee FROM  `sessioncourante` );
SET a=(SELECT semestre FROM  `sessioncourante` );

    
delete from `moduleevaluation` where sigle=New.sigle and annee=b and semestre=a;
     IF NEW.typeModule='Cours' OR NEW.typeModule='Cours-Labos'
THEN 
`sigle` ,
`idEvaluation` ,
`ponderation` ,
`semestre` ,
`annee`
)
VALUES 
(NEW.sigle,  '1',  '40',  a,  b),
(NEW.sigle,  '2',  '60',  a,  b),
(NEW.sigle,  '4',  ' ',  a,  b);

ELSE

`sigle` ,
`idEvaluation` ,
`ponderation` ,
`semestre` ,
`annee`
)
VALUES 
(NEW.sigle,  '3',  '100',  a,  b),
(NEW.sigle,  '4',  ' ',  a,  b);

END IF;
END
//
DELIMITER ;
DROP TRIGGER IF EXISTS `before_update_module`;
DELIMITER //
CREATE TRIGGER `before_update_module` BEFORE UPDATE ON `module`
 FOR EACH ROW BEGIN
DECLARE a,b  int;
SET b=(SELECT annee FROM  `sessioncourante` );
SET a=(SELECT semestre FROM  `sessioncourante` );

    
delete from `moduleevaluation` where sigle=New.sigle and annee=b and semestre=a;
     IF NEW.typeModule='Cours' OR NEW.typeModule='Cours-Labos'
THEN 
`sigle` ,
`idEvaluation` ,
`ponderation` ,
`semestre` ,
`annee`
)
VALUES 
(NEW.sigle,  '1',  '40',  a,  b),
(NEW.sigle,  '2',  '60',  a,  b),
(NEW.sigle,  '4',  ' ',  a,  b);

ELSE

`sigle` ,
`idEvaluation` ,
`ponderation` ,
`semestre` ,
`annee`
)
VALUES 
(NEW.sigle,  '3',  '100',  a,  b),
(NEW.sigle,  '4',  ' ',  a,  b);

END IF;
END
//
DELIMITER ;

