--
-- Structure for view `exam`
--
DROP TABLE IF EXISTS `exam`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `exam` AS select `p`.`matriculeEtudiant` AS `matriculeEtudiant`,`p`.`sigle` AS `sigle`,`replaceWithZero`(ifnull(`p`.`note`,0)) AS `note`,'CC' AS `ev`,(((round((`p`.`annee` % 100),0) * 100) + round((`p`.`annee` % 100),0)) + 1) AS `annee`,`p`.`idEvaluation` AS `idEvaluation`,`u`.`semestre` AS `semestre`,`p`.`annee` AS `year`,`p`.`semestre` AS `semestreB` from ((`notespartielles_a_s` `p` join `module` `m`) join `unite` `u`) where ((convert(`p`.`sigle` using utf8) = `m`.`sigle`) and (`m`.`sigleunite` = `u`.`sigle`) and (`p`.`idEvaluation` = 2) and (`p`.`semestre` = 3)) union select `p`.`matriculeEtudiant` AS `matriculeEtudiant`,`p`.`sigle` AS `sigle`,`replaceWithZero`(ifnull(`p`.`note`,0)) AS `note`,'CC' AS `ev`,((round(((`p`.`annee` % 100) - 1),0) * 100) + round((`p`.`annee` % 100),0)) AS `annee`,`p`.`idEvaluation` AS `idEvaluation`,`u`.`semestre` AS `semestre`,`p`.`annee` AS `year`,`p`.`semestre` AS `semestreB` from ((`notespartielles_a_s` `p` join `module` `m`) join `unite` `u`) where ((convert(`p`.`sigle` using utf8) = `m`.`sigle`) and (`m`.`sigleunite` = `u`.`sigle`) and (`p`.`idEvaluation` = 2) and (`p`.`semestre` = 1));

