')) or ((`p2`.`annee` = 2017) and (`p2`.`semestre` = 1) and (`p2`.`sigle` like '___6%')))))))) union select distinct `p1`.`matriculeEtudiant` AS `matriculeetudiant`,'L1' AS `niveau`,`e`.`nom` AS `nomE`,`e`.`prenom` AS `prenom`,`e`.`dateNaissance` AS `dateNaissance`,`e`.`lieuNaissance` AS `lieuNaissance`,`f`.`nom` AS `nom`,`i`.`num_bac` AS `num_bac`,`i`.`infoBac` AS `infobac`,`e`.`nationalite` AS `nationalite`,`d`.`idProgramme` AS `idProgramme` from ((((`planetudes` `p1` join `etudiant` `e`) join `dossieretudiant` `d`) join `programme` `f`) join `etudesanterieures` `i`) where ((`p1`.`matriculeEtudiant` = `e`.`matriculeEtudiant`) and (`p1`.`matriculeEtudiant` = `d`.`matriculeEtudiant`) and (`d`.`idProgramme` = `f`.`idProgramme`) and (`e`.`infoBac` = `i`.`idInfoBac`) and (((`p1`.`annee` = 2016) and (`p1`.`semestre` = 3) and (`p1`.`sigle` like '___1%')) or ((`p1`.`annee` = 2017) and (`p1`.`semestre` = 1) and (`p1`.`sigle` like '___2%'))) and (not(exists(select `p2`.`matriculeEtudiant` from `planetudes` `p2` where ((`p2`.`matriculeEtudiant` = `p1`.`matriculeEtudiant`) and (((`p2`.`annee` = 2016) and (`p2`.`semestre` = 3) and ((`p2`.`sigle` like '___5%') or (`p2`.`sigle` like '___3%'))) or ((`p2`.`annee` = 2017) and (`p2`.`semestre` = 1) and ((`p2`.`sigle` like '___6%') or (`p2`.`sigle` like '___4%')))))))));

