CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `notes_globales` AS select `c`.`matriculeEtudiant` AS `matriculeEtudiant`,`c`.`sigle` AS `sigle`,`c`.`noteCC` AS `noteCC`,`c`.`noteExam` AS `noteExam`,`e`.`note` AS `noteRT`,`c`.`annee` AS `annee`,`c`.`semestre` AS `semestre`,`c`.`year` AS `year`,`c`.`semestreB` AS `semestreB` from (`cc_exam` `c` left join `examrt` `e` on(((`c`.`sigle` = `e`.`sigle`) and (`c`.`matriculeEtudiant` = `e`.`matriculeEtudiant`) and (`c`.`semestre` = `e`.`semestre`) and (`c`.`annee` = `e`.`annee`)))) union select `e`.`matriculeEtudiant` AS `matriculeEtudiant`,`e`.`sigle` AS `sigle`,`c`.`noteCC` AS `noteCC`,`c`.`noteExam` AS `noteExam`,`e`.`note` AS `noteRT`,`e`.`annee` AS `annee`,`e`.`semestre` AS `semestre`,`e`.`year` AS `year`,`e`.`semestreB` AS `semestreB` from (`examrt` `e` left join `cc_exam` `c` on(((`c`.`sigle` = `e`.`sigle`) and (`c`.`matriculeEtudiant` = `e`.`matriculeEtudiant`) and (`c`.`semestre` = `e`.`semestre`) and (`c`.`annee` = `e`.`annee`))));

